#include <string>

template<class T>
T larger(T a, T b) {
    return a < b ? b : a;
}

template<class T, class U>
bool less_than(T left, U right) {
    return left < right;
}

void demo() {
    int high = larger(3, 5);            // T deduced as int

    // larger(1, 2.0) is an error: the arguments propose int and double
    // for one parameter and deduction will not convert to reconcile them.
    double mixed = larger<double>(1, 2.0);  // T fixed; 1 converts to 1.0

    bool ordered = less_than(1, 2.0);   // two parameters, T=int U=double

    // larger("alpha", "beta") deduces T = const char* and compares
    // pointer values, not text. Construct strings to compare lexically.
    std::string text = larger(std::string{"alpha"}, std::string{"beta"});

    (void)high; (void)mixed; (void)ordered; (void)text;
}

#include <cstddef>
#include <type_traits>
#include <vector>

// Function template
template<class T>
T square(T value) {
    return value * value;
}

// Class template
template<class T>
class Buffer {
public:
    explicit Buffer(std::size_t count) : data_(count) {}
    T& operator[](std::size_t index) { return data_[index]; }

private:
    std::vector<T> data_;
};

// Variable template
template<class T>
constexpr T zero = T{};

// Alias template: names std::vector<T>, it does not create a new type.
template<class T>
using Vec = std::vector<T>;

static_assert(std::is_same_v<Vec<int>, std::vector<int>>);

void use() {
    int squared = square(7);       // deduced: T is int
    Buffer<double> prices{64};     // spelled: T is double
    double origin = zero<double>;  // spelled
    Vec<int> quantities{1, 2, 3};  // spelled; same type as std::vector<int>

    (void)squared; (void)prices; (void)origin; (void)quantities;
}

#include <concepts>
#include <cstddef>
#include <functional>
#include <string>

// Constrained template parameter.
template<std::integral T>
T checked_max(T a, T b) {
    return a < b ? b : a;
}

// requires clause: the same constraint in another position.
template<class T>
    requires std::integral<T>
T checked_min(T a, T b) {
    return b < a ? b : a;
}

// Abbreviated template.
void send(std::integral auto value) { (void)value; }

template<class T>
concept Hashable = requires(T value) {
    { std::hash<T>{}(value) } -> std::convertible_to<std::size_t>;
};

static_assert(Hashable<int>);
static_assert(Hashable<std::string>);

// All of the above is checked by the compiler; the generated code for a
// constrained template is identical to the unconstrained one.
void use() {
    (void)checked_max(8, 13);
    (void)checked_min(8, 13);
    send(3);
}

#include <iostream>

struct Order {
    double price;
    int quantity;
};

void inspect_closures() {
    double limit = 100.0;

    // Unique, unnamed closure type: auto is the only practical spelling.
    auto over = [limit](const Order& order) {
        return order.price > limit;
    };

    struct Over {
        double limit;  // one data member for the one capture

        // const, because a lambda's operator() is const unless mutable.
        bool operator()(const Order& order) const {
            return order.price > limit;
        }
    };

    Over over_by_hand{limit};
    Order order{101.25, 50};

    std::cout << std::boolalpha
              << over(order) << ' '
              << over_by_hand(order) << ' '
              << (sizeof(over) == sizeof(double)) << '\n';
}

// BROKEN: n dies when the function returns; the closure keeps only a
// reference, which never extends a lifetime. Calling the result reads a
// destroyed object -- undefined behaviour.
//
//   auto make_bad_adder(int n) {
//       return [&n](int x) { return x + n; };
//   }

auto make_adder(int n) {
    return [n](int x) { return x + n; };  // the value travels with the closure
}

// Capture rules:
//  - Capture by value when the lambda is returned, stored, or queued.
//  - Capture by reference only when the lambda is consumed immediately
//    and the referent clearly outlives the call.
//  - A copied pointer, reference wrapper, or view is a lifetime
//    dependency even though the capture itself is by value.
//  - Recheck captures whenever an immediate lambda becomes a stored or
//    asynchronous callback.

int use() {
    auto add_five = make_adder(5);
    return add_five(3);  // 8
}

#include <algorithm>
#include <iostream>
#include <vector>

struct Order {
    double price;
    int quantity;
};

struct Quote {
    double price;
};

// One closure type; its operator() is a template, so each call
// instantiates a suitable version.
auto less_price = [](const auto& left, const auto& right) {
    return left.price < right.price;
};

void sort_both() {
    std::vector<Order> orders{{100.25, 10}, {99.95, 30}, {100.10, 20}};
    std::vector<Quote> quotes{{100.10}, {99.95}};

    // std::sort is instantiated with less_price's exact concrete type,
    // so the comparator body is visible inside that instantiation and
    // can be inlined. A comparator passed as a function pointer is a
    // runtime value; unless the optimizer can prove its target, the
    // call site must issue an indirect call it cannot inline through.
    std::sort(orders.begin(), orders.end(), less_price);
    std::sort(quotes.begin(), quotes.end(), less_price);

    std::cout << orders.front().price << ' ' << quotes.front().price << '\n';
}
